#include "update/serial_control.h"
#include <cassert>
#include <cstring>
using namespace groove::update;
static SerialCommand feed(SerialControl& p,const char* text){SerialCommand result=SerialCommand::None;while(*text){auto next=p.feed(uint8_t(*text++));if(next!=SerialCommand::None){assert(result==SerialCommand::None);result=next;}}return result;}
int main(){SerialControl p;assert(feed(p,"!GBX1 DEPLOYCHECK\n")==SerialCommand::DeployCheck);assert(feed(p,"!GBX1 OPTTEST\n")==SerialCommand::OptimizationTest);assert(feed(p,"!GBX1 EFFSAMPLER\n")==SerialCommand::EfficiencySampler);assert(feed(p,"!GBX1 EFFICIENCY\n")==SerialCommand::Efficiency);assert(feed(p,"!GBX1 EFFTAIL\n")==SerialCommand::EfficiencyTail);assert(feed(p,"!GBX1 FINALTEST\n")==SerialCommand::FinalTest);assert(feed(p,"!GBX1 WAVE4TEST\n")==SerialCommand::Wave4Test);assert(feed(p,"!GBX1 PRESETCHECK\n")==SerialCommand::PresetCheck);assert(feed(p,"!GBX1 INPUTTEST\n")==SerialCommand::InputTest);assert(feed(p,"!GBX1 AUDIOTEST\n")==SerialCommand::AudioTest);assert(feed(p,"!GBX1 NATIVETEST\n")==SerialCommand::NativeTest);assert(feed(p,"!GBX1 MIDITEST\n")==SerialCommand::MidiTest);assert(feed(p,"!GBX1 UITEST\n")==SerialCommand::UiTest);assert(feed(p,"!GBX1 KITREC\n")==SerialCommand::KitRecordTest);assert(feed(p,"!GBX1 CHOPTEST\n")==SerialCommand::ChopTest);assert(feed(p,"!GBX1 KITSWAP\n")==SerialCommand::KitSwap);assert(feed(p,"!GBX1 SAVETEST\n")==SerialCommand::SaveTest);assert(feed(p,"!GBX1 FXSTRESS\n")==SerialCommand::FxStress);assert(feed(p,"!GBX1 DRUMDEMO\n")==SerialCommand::DrumDemo);assert(feed(p,"!GBX1 LOOPTEST\n")==SerialCommand::LoopTest);assert(feed(p,"!GBX1 SAMPLETEST\n")==SerialCommand::SampleTest);assert(feed(p,"!GBX1 STATUS\r\n")==SerialCommand::Status);assert(feed(p,"!GBX1 LOG\n")==SerialCommand::Log);assert(feed(p,"!GBX1 BENCHMARK\n")==SerialCommand::Benchmark);assert(feed(p,"!GBX1 HARDWARE\n")==SerialCommand::Hardware);assert(feed(p,"!GBX1 PLSTRESS\n")==SerialCommand::PlaitsStress);assert(feed(p,"!GBX1 PLFAST\n")==SerialCommand::PlaitsFast);assert(feed(p,"!GBX1 ENTER\n")==SerialCommand::Enter);assert(feed(p,"!GBX1 TRIAL\n")==SerialCommand::Trial);assert(feed(p,"!GBX1 CONFIRM\n")==SerialCommand::Confirm);assert(feed(p,"!GBX1 BOOT\n")==SerialCommand::Boot);assert(feed(p,"!GBX1 CANCEL\n")==SerialCommand::Cancel);assert(feed(p,"!GBX1 ETHERNET\n")==SerialCommand::Ethernet);assert(feed(p,"!GBX1 WIFI\n")==SerialCommand::Wifi);assert(feed(p,"!GBX1 USB\n")==SerialCommand::Usb);assert(feed(p,"noise !GBX1 ENTER\n")==SerialCommand::None);assert(feed(p,"!GBX1 ENTER extra\n")==SerialCommand::None);assert(feed(p,"!GBX1 ENTER") == SerialCommand::None);assert(feed(p,"..........................................................\n")==SerialCommand::None);assert(feed(p,"!GBX1 STATUS\n")==SerialCommand::Status);}
